import { toast } from 'sonner'
import { m } from '#/paraglide/messages.js'

/**
 * Registers the offline service worker (production only; it is generated by the build). When a new
 * version is waiting, the user decides when to reload, so nothing they are typing is lost.
 */
export function registerServiceWorker() {
  if (!import.meta.env.PROD || !('serviceWorker' in navigator)) return

  const hadController = navigator.serviceWorker.controller !== null
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    // The first install also takes control; only a replaced version needs a reload.
    if (hadController) window.location.reload()
  })

  navigator.serviceWorker
    .register('/sw.js')
    .then((registration) => {
      if (registration.waiting && hadController)
        offerUpdate(registration.waiting)
      registration.addEventListener('updatefound', () => {
        const worker = registration.installing
        worker?.addEventListener('statechange', () => {
          if (
            worker.state === 'installed' &&
            navigator.serviceWorker.controller
          ) {
            offerUpdate(worker)
          }
        })
      })
    })
    .catch((error: unknown) => {
      console.error('Could not register the service worker', error)
    })
}

function offerUpdate(worker: ServiceWorker) {
  toast(m.update_ready(), {
    duration: Number.POSITIVE_INFINITY,
    action: {
      label: m.update_reload(),
      onClick: () => worker.postMessage('skip-waiting'),
    },
  })
}
